code.cpp:
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    int count = 0;
    for (long long d = 1; d * d <= n; d++) {
        if (n % d == 0) {
            if (d * d == n) {
                count += 1;
            } else {
                count += 2;
            }
        }
    }
    cout << count << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        int count = 0;
        for (long d = 1; d * d <= n; d++) {
            if (n % d == 0) {
                if (d * d == n) {
                    count += 1;
                } else {
                    count += 2;
                }
            }
        }
        System.out.println(count);
    }
}
